with flattened_attrs as (select id, coupon_codes, ship_to, ship_to.city as ship_city, forall(items, item -> item.qty <= 5) as all_small_qty, coalesce(attributes['gift'], 'unknown') as gift_or_default, size(items) as num_items from carts) select id, ship_city, gift_or_default, sum(num_items) over (order by num_items, id rows between unbounded preceding and current row) as cumulative_num_items, avg(num_items) over w_ordered as num_items_avg_2, avg(num_items) over (order by num_items, id rows between 3 preceding and current row) as num_items_avg_3, row_number() over w_grp as seq_no, row_number() over w_grp as seq_no_2 from flattened_attrs window w_ordered as (partition by ship_city order by num_items, id rows between 2 preceding and current row), w_grp as (partition by ship_city order by num_items desc, id);
